    for (int i = 0; i < n; i++) {
        string suffix = str.substr(i);
        if (is_palindrome(suffix)) {
            // The prefix is the part before the palindromic suffix
            string prefix = str.substr(0, i);

            // Reverse the prefix
            string rev_prefix(prefix.rbegin(), prefix.rend());

            // The shortest palindrome is the original string + reversed prefix
            return str + rev_prefix;
        }
    }
    return str; 
}
