  // In JavaScript, 'eval()' evaluates a string as code.
  // Note: For floor division (//), JS uses Math.floor() or bitwise operators,
  // but since the input specifies '//', we must handle that specifically 
  // because 'eval' treats '//' as a comment.

  // Replace '//' with a logic that performs floor division.
  // However, since eval() cannot handle custom operators easily, 
  // we can replace '//' with a function call or use a different approach.

  // To handle '//' (Floor Division) and '**' (Exponentiation) correctly:
  // We replace '//' with a temporary placeholder or handle it via a regex 
  // if we want to strictly follow the 'eval' path.

  // A more robust way to handle the specific '//' requirement in JS:
  const sanitizedExpression = expression.replace(/\s*\/\/\s*/g, '/');

  // Note: In JS, (a / b) | 0 or Math.floor(a / b) is floor division.
  // Since the prompt asks for the evaluation of the expression:
  const result = eval(sanitizedExpression);

  // To ensure floor division for the result of any division:
  return Math.floor(result);
