// GetRow finds all occurrences of integer x in a 2D slice.
// It returns a list of coordinates [row, col].
// The results are sorted by row ascending, and then by column descending.
func GetRow(lst [][]int, x int) [][2]int {
	var result [][2]int

	for r, row := range lst {
		var rowCoords []int
		for c, val := range row {
			if val == x {
				rowCoords = append(rowCoords, c)
			}
		}

		// Sort columns in descending order for the current row
		sort.Slice(rowCoords, func(i, j int) bool {
			return rowCoords[i] > rowCoords[j]
		})

		// Append the sorted column coordinates to the final result
		for _, c := range rowCoords {
			result = append(result, [2]int{r, c})
		}
	}

	return result
}
