		}
		if v > max {
			max = v
		}
	}

	// Calculate the range
	diff := max - min

	// Handle the edge case where all numbers in the list are the same
	// to avoid division by zero.
	if diff == 0 {
		return make([]float64, len(numbers))
	}

	// Create a new slice for the results to avoid mutating the input
	rescaled := make([]float64, len(numbers))
	for i, v := range numbers {
		// Linear transformation formula: (x - min) / (max - min)
		rescaled[i] = (v - min) / diff
	}

	return rescaled
}
