            for (int c = row.size() - 1; c >= 0; c--) {
                // Check if the element at the current coordinate matches x
                // Using .equals() or comparing primitive int values
                if (row.get(c) != null && row.get(c) == x) {
                    // Add the coordinate [row, col] to the result list
                    result.add(Arrays.asList(r, c));
                }
            }
        }

        return result;
    }
