// You are given an array arr of integers and you need to return
// sum of magnitudes of integers multiplied by product of all signs
// of each number in the array, represented by 1, -1 or 0.
// Note: return nil for empty arr.
// 
// Example:
// >>> ProdSigns([1, 2, 2, -4]) == -9
// >>> ProdSigns([0, 1]) == 0
// >>> ProdSigns([]) == nil
func ProdSigns(arr []int) interface{} {
	if len(arr) == 0 {
		return nil
	}

	sumMagnitudes := 0
	prodSigns := 1

	for _, val := range arr {
		// Calculate magnitude (absolute value)
		if val < 0 {
			sumMagnitudes += -val
		} else {
			sumMagnitudes += val
		}

		// Calculate sign product
		if val > 0 {
			prodSigns *= 1
		} else if val < 0 {
			prodSigns *= -1
		} else {
			prodSigns *= 0
		}
	}

	return sumMagnitudes * prodSigns
}
