// GetClosestVowel finds the closest vowel that stands between
// two consonants from the right side of the word (case sensitive).
func GetClosestVowel(word string) string {
	if len(word) < 3 {
		return ""
	}

	// Helper function to check if a character is a vowel
	isVowel := func(r byte) bool {
		return strings.ContainsAny(string(r), "aeiouAEIOU")
	}

	// Helper function to check if a character is a consonant
	// Since the input is guaranteed to be English letters only,
	// any letter that isn't a vowel is a consonant.
	isConsonant := func(r byte) bool {
		return !isVowel(r)
	}

	// Iterate from the right side of the word.
	// Vowels at the beginning (index 0) and ending (index len-1) don't count,
	// so we start at len-2 and end at 1.
	for i := len(word) - 2; i >= 1; i-- {
		char := word[i]
		if isVowel(char) {
			// Check if the characters to the left and right are consonants
			if isConsonant(word[i-1]) && isConsonant(word[i+1]) {
				return string(char)
			}
		}
	}

	return ""
}
