// FixSpaces replaces all spaces in a string with underscores.
// If there are more than 2 consecutive spaces, they are replaced by a single hyphen.
func FixSpaces(text string) string {
	var result strings.Builder
	n := len(text)

	for i := 0; i < n; {
		// If we encounter a space, we need to count how many consecutive spaces there are
		if text[i] == ' ' {
			count := 0
			for i < n && text[i] == ' ' {
				count++
				i++
			}

			if count > 2 {
				// Rule: more than 2 consecutive spaces are replaced by a single '-'
				result.WriteByte('-')
			} else {
				// Rule: 1 or 2 spaces are replaced by underscores (one underscore per space)
				for j := 0; j < count; j++ {
					result.WriteByte('_')
				}
			}
		} else {
			// If it's not a space, just append the character and move to the next
			result.WriteByte(text[i])
			i++
		}
	}

	return result.String()
}
