        if (date == null || date.isEmpty()) {
            return false;
        }

        // Rule 4: The date should be in the format: mm-dd-yyyy
        // A valid mm-dd-yyyy string must be exactly 10 characters long
        if (date.length() != 10) {
            return false;
        }

        // Check if the separators are hyphens at the correct positions
        if (date.charAt(2) != '-' || date.charAt(5) != '-') {
            return false;
        }

        try {
            // Split the string into month, day, and year
            String[] parts = date.split("-");

            // Ensure we have exactly 3 parts (month, day, year)
            if (parts.length != 3) {
                return false;
            }

            int month = Integer.parseInt(parts[0]);
            int day = Integer.parseInt(parts[1]);
            int year = Integer.parseInt(parts[2]);

            // Rule 3: The months should not be less than 1 or higher than 12
            if (month < 1 || month > 12) {
                return false;
            }

            // Rule 2: Day validation based on the month
            if (day < 1) {
                return false;
            }

            if (month == 2) {
                // February: max 29 days (as per the specific rules provided)
                if (day > 29) {
                    return false;
                }
            } else if (month == 4 || month == 6 || month == 9 || month == 11) {
                // April, June, September, November: max 30 days
                if (day > 30) {
                    return false;
                }
            } else {
                // January, March, May, July, August, October, December: max 31 days
                if (day > 31) {
                    return false;
                }
            }

            return true;
        } catch (NumberFormatException e) {
            // If any part of the date is not a valid integer, it's an invalid date
            return false;
        }
    }
}
