    let num = (l + 2) / 3;
    let mut output = String::new();

    for i in 0..num {
        let group = &s[i * 3..std::cmp::min(l, (i + 1) * 3)];

        // If the group has exactly 3 characters, reverse the cycle:
        // Encoded [0, 1, 2] was Original [2, 0, 1]
        if group.len() == 3 {
            let x = format!("{}{}{}", &group[2..3], &group[0..1], &group[1..2]);
            output.push_str(&x);
        } else {
            // Groups with fewer than 3 characters were not changed during encoding
            output.push_str(group);
        }
    }
    output
}

fn main() {
    let original = "abcdefg";
    let encoded = encode_cyclic(original);
    let decoded = decode_cyclic(&encoded);

    println!("Original: {}", original); // abcdefg
    println!("Encoded:  {}", encoded);  // bcaefdg
    println!("Decoded:  {}", decoded);  // abcdefg
}

pub fn encode_cyclic(s: &str) -> String {
    let l = s.len();
    let num = (l + 2) / 3;
    let mut output = String::new();
    for i in 0..num {
        let group = &s[i * 3..std::cmp::min(l, (i + 1) * 3)];
        if group.len() == 3 {
            let x = format!("{}{}{}", &group[1..2], &group[2..3], &group[0..1]);
            output.push_str(&x);
        } else {
            output.push_str(group);
        }
    }
    output
}
```

### Explanation of the Logic:
1. **Grouping**: Just like the encoder, we iterate through the string in chunks of 3.
2. **The Shift**: 
   - **Encoding**: `Original[0, 1, 2]` $\rightarrow$ `Encoded[1, 2, 0]`
   - **Decoding**: `Encoded[0, 1, 2]` $\rightarrow$ `Original[2, 0, 1]`
   - Therefore, we take the character at index 2 of the encoded group and place it first, followed by the characters at index 0 and 1.
3. **Edge Cases**: If the remaining string is shorter than 3 characters, it is appended as-is, mirroring the behavior of the `encode_cyclic` function.

**Note on Safety**: This code uses byte-indexing (`&group[0..1]`), which is safe for ASCII strings. If your input contains multi-byte UTF-8 characters (like emojis or non-English scripts), you should convert the string to a `Vec<char>` first to avoid panicking on character boundaries.

