/*
  Given a dictionary, return true if all keys are strings in lower 
  case or all keys are strings in upper case, else return false.
  The function should return false if the given dictionary is empty.
  Examples:
  checkDictCase({"a":"apple", "b":"banana"}) should return true.
  checkDictCase({"a":"apple", "A":"banana", "B":"banana"}) should return false.
  checkDictCase({"a":"apple", 8:"banana", "a":"apple"}) should return false.
  checkDictCase({"Name":"John", "Age":"36", "City":"Houston"}) should return false.
  checkDictCase({"STATE":"NC", "ZIP":"12345" }) should return true.
*/
const checkDictCase = (dict) => {
  const keys = Object.keys(dict);

  // Return false if the dictionary is empty
  if (keys.length === 0) {
    return false;
  }

  /**
   * A key is considered "lowercase" if it is equal to its lowercase version
   * AND it is not equal to its uppercase version (ensuring it contains 
   * actual letters and isn't just a number or symbol).
   */
  const isLower = (k) => k === k.toLowerCase() && k !== k.toUpperCase();

  /**
   * A key is considered "uppercase" if it is equal to its uppercase version
   * AND it is not equal to its lowercase version.
   */
  const isUpper = (k) => k === k.toUpperCase() && k !== k.toLowerCase();

  // Check if every key satisfies the lowercase condition OR every key satisfies the uppercase condition
  const allLower = keys.every(isLower);
  const allUpper = keys.every(isUpper);

  return allLower || allUpper;
};
